const symbols = $input.all()[0].json.symbols || ['BTC-USD', 'ETH-USD'];
const enable_stale = $input.all()[0].json.enable_stale_while_revalidate !== false;

// Check CASD cache for each symbol
const results = [];
for (const symbol of symbols) {
  const cache_key = `datafeed:${symbol}`;
  const cached = await casd.get(cache_key);

  if (cached && !cached.expired) {
    results.push({...cached.data, cache_status: 'HIT'});
  } else if (cached && enable_stale) {
    results.push({...cached.data, cache_status: 'STALE_SERVING'});
  } else {
    results.push({symbol, cache_status: 'MISS'});
  }
}

return [{json: {results, needs_fetch: results.filter(r => r.cache_status !== 'HIT').map(r => r.symbol)}}];

const primary = $input.all()[0].json;
const mirror = $input.all()[1]?.json;

// Schema normalization
const normalized = [];

if (primary && primary.bitcoin) {
  normalized.push({
    symbol: 'BTC-USD',
    price: primary.bitcoin.usd,
    change_24h: primary.bitcoin.usd_24h_change || 0,
    volume: primary.bitcoin.usd_24h_vol || 0,
    timestamp: new Date().toISOString(),
    source: 'coingecko',
    cache_status: 'FRESH'
  });
}

if (primary && primary.ethereum) {
  normalized.push({
    symbol: 'ETH-USD',
    price: primary.ethereum.usd,
    change_24h: primary.ethereum.usd_24h_change || 0,
    volume: primary.ethereum.usd_24h_vol || 0,
    timestamp: new Date().toISOString(),
    source: 'coingecko',
    cache_status: 'FRESH'
  });
}

// Fallback to mirror if primary failed
if (normalized.length === 0 && mirror && mirror.data && mirror.data.rates) {
  normalized.push({
    symbol: 'BTC-USD',
    price: parseFloat(mirror.data.rates.USD),
    change_24h: 0,
    volume: 0,
    timestamp: new Date().toISOString(),
    source: 'coinbase_mirror',
    cache_status: 'FRESH'
  });
}

// Write to CASD cache
for (const item of normalized) {
  const cache_key = `datafeed:${item.symbol}`;
  await casd.set(cache_key, item, {ttl: 60}); // 60 second TTL
}

return normalized.map(item => ({json: item}));
